// AdminChannelStats is the resolver for the adminChannelStats field.
func (r *queryResolver) AdminChannelStats(ctx context.Context, typeArg string) (*ChannelStats, error) {
	userRole, ok := ctx.Value(ctxKeyUserRole).(string)
	if !ok || userRole != "admin" {
		return nil, fmt.Errorf("unauthorized: admin access required")
	}

	var sent, failed int
	var lastSent sql.NullTime
	if err := database.QueryRowContext(ctx, r.ServerDB, database.TimeoutSimpleSelect, `
		SELECT
			COUNT(CASE WHEN state = 'delivered' THEN 1 END),
			COUNT(CASE WHEN state IN ('failed', 'dead_letter') THEN 1 END),
			MAX(delivered_at)
		FROM notification_queue
		WHERE channel_type = ?
	`, typeArg).Scan(&sent, &failed, &lastSent); err != nil {
		return nil, fmt.Errorf("failed to load channel stats: %w", err)
	}

	var lastSentAt *time.Time
	if lastSent.Valid {
		lastSentAt = &lastSent.Time
	}

	return &ChannelStats{
		Sent:     sent,
		Failed:   failed,
		LastSent: lastSentAt,
	}, nil
}

// AdminQueueStats is the resolver for the adminQueueStats field.
func (r *queryResolver) AdminQueueStats(ctx context.Context) (*QueueStats, error) {
	userRole, ok := ctx.Value(ctxKeyUserRole).(string)
	if !ok || userRole != "admin" {
		return nil, fmt.Errorf("unauthorized: admin access required")
	}

	var pending, processing, completed, failed int
	if err := database.QueryRowContext(ctx, r.ServerDB, database.TimeoutSimpleSelect, "SELECT COUNT(*) FROM notification_queue WHERE state IN ('created', 'queued')").Scan(&pending); err != nil {
		return nil, fmt.Errorf("failed to load pending queue count: %w", err)
	}
	if err := database.QueryRowContext(ctx, r.ServerDB, database.TimeoutSimpleSelect, "SELECT COUNT(*) FROM notification_queue WHERE state = 'sending'").Scan(&processing); err != nil {
		return nil, fmt.Errorf("failed to load processing queue count: %w", err)
	}
	if err := database.QueryRowContext(ctx, r.ServerDB, database.TimeoutSimpleSelect, "SELECT COUNT(*) FROM notification_queue WHERE state = 'delivered'").Scan(&completed); err != nil {
		return nil, fmt.Errorf("failed to load completed queue count: %w", err)
	}
	if err := database.QueryRowContext(ctx, r.ServerDB, database.TimeoutSimpleSelect, "SELECT COUNT(*) FROM notification_queue WHERE state IN ('failed', 'dead_letter')").Scan(&failed); err != nil {
		return nil, fmt.Errorf("failed to load failed queue count: %w", err)
	}

	return &QueueStats{
		Pending:    pending,
		Processing: processing,
		Completed:  completed,
		Failed:     failed,
	}, nil
}

// AdminSMTPProviders is the resolver for the adminSMTPProviders field.
func (r *queryResolver) AdminSMTPProviders(ctx context.Context) ([]*SMTPProvider, error) {
	userRole, ok := ctx.Value(ctxKeyUserRole).(string)
	if !ok || userRole != "admin" {
		return nil, fmt.Errorf("unauthorized: admin access required")
	}

	presets := service.ListProviderPresets()
	providers := make([]*SMTPProvider, 0, len(presets))
	for _, preset := range presets {
		port, err := strconv.Atoi(preset.Port)
		if err != nil {
			return nil, fmt.Errorf("invalid SMTP preset port %q for %s: %w", preset.Port, preset.Name, err)
		}

		providers = append(providers, &SMTPProvider{
			Name:   preset.Name,
			Host:   preset.Host,
			Port:   port,
			Secure: preset.UseTLS,
		})
	}

	return providers, nil
}

// AdminPasskeys is the resolver for the adminPasskeys field.
// Returns the passkeys registered for the currently authenticated admin.
func (r *queryResolver) AdminPasskeys(ctx context.Context) ([]*AdminPasskey, error) {
	userRole, ok := ctx.Value(ctxKeyUserRole).(string)
	if !ok || userRole != "admin" {
		return nil, fmt.Errorf("unauthorized: admin access required")
	}

	admin, err := loadGraphQLCurrentAdmin(ctx, r.adminAccountsDB())
	if err != nil {
		return nil, err
	}

	summaries, err := handler.ListAdminPasskeys(r.adminAccountsDB(), admin.ID)
	if err != nil {
		return nil, err
	}

	out := make([]*AdminPasskey, 0, len(summaries))
	for _, s := range summaries {
		out = append(out, mapGraphQLAdminPasskey(s))
	}
	return out, nil
}

